_CORE_SRC = '# Action format: "[(from_node, to_node, count), ...]"\n# Payout: "a > b": full reward; "a == b >= 1": reward / 2 each;\n# "a == b == 0": the order stays open. The larger positive side wins.\n# Cost: "UPKEEP = 1.0" per unit away from its own base, each turn,\n# after movement. Units at their own base cost nothing.\n\nimport heapq\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 60\nUPKEEP = 1.0\n\n\ndef payout(own, opponent, reward):\n    """Exact revenue of both players for a single order."""\n    if own == 0 and opponent == 0:\n        return 0.0, 0.0\n    if own > opponent:\n        return float(reward), 0.0\n    if opponent > own:\n        return 0.0, float(reward)\n    half = reward / 2.0\n    return half, half\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        row = [-1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbor in adjacency[node]:\n                if row[neighbor] < 0:\n                    row[neighbor] = row[node] + 1\n                    queue.append(neighbor)\n        distances.append(row)\n    return adjacency, distances\n\n\ndef legal_action(have, targets, adjacency, distances):\n    """Closest-first transport, checked against start-of-turn availability."""\n    n = len(have)\n    surplus = [max(0, have[v] - targets[v]) for v in range(n)]\n    deficit = [max(0, targets[v] - have[v]) for v in range(n)]\n    pairs = sorted(\n        (distances[s][t], s, t)\n        for s in range(n) if surplus[s]\n        for t in range(n) if deficit[t] and distances[s][t] > 0\n    )\n\n    moves = {}\n    # Records describe intended missions after this turn, not fictional arrivals.\n    missions = {}\n    for v in range(n):\n        kept = min(have[v], targets[v])\n        if kept:\n            missions[(v, v)] = kept\n\n    for _, source, target in pairs:\n        count = min(surplus[source], deficit[target])\n        if count <= 0:\n            continue\n        hop = next(\n            v for v in adjacency[source]\n            if distances[v][target] == distances[source][target] - 1\n        )\n        surplus[source] -= count\n        deficit[target] -= count\n        moves[(source, hop)] = moves.get((source, hop), 0) + count\n        missions[(hop, target)] = missions.get((hop, target), 0) + count\n\n    available = list(have)\n    action = []\n    for (source, destination), count in sorted(moves.items()):\n        if destination not in adjacency[source] or source == destination:\n            continue\n        count = min(count, available[source])\n        if count > 0:\n            available[source] -= count\n            action.append((int(source), int(destination), int(count)))\n    return action, missions\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_key = None\n        self.adjacency = []\n        self.distances = []\n        self.missions = {}\n        self.previous_turn = None\n        self.bad_reports = 0\n\n    def _plan(self, obs, deadline):\n        n = obs["n_nodes"]\n        base = obs["player_base"]\n        have = obs["player_units"]\n        enemy = obs["opponent_units"]\n        remaining = max(0, N_TURNS - obs["turn"])\n        distances = self.distances\n        targets = [0] * n\n\n        # Units are only distinguished by their actual source and previous mission.\n        units = []\n        for source in range(n):\n            left = have[source]\n            if self.previous_turn == obs["turn"] - 1:\n                for (location, target), count in sorted(self.missions.items()):\n                    if location == source:\n                        take = min(left, count)\n                        units.extend((source, target) for _ in range(take))\n                        left -= take\n            units.extend((source, base) for _ in range(left))\n\n        orders = [[] for _ in range(n)]\n        for node, reward, turns_left in obs.get("orders", []):\n            orders[node].append((reward, min(turns_left, remaining)))\n\n        unresolved = [v for v in range(n) if orders[v]]\n        # The winner-take-all payout is NOT concave. Evaluate complete winning\n        # or tying bundles rather than getting stuck at zero marginal value.\n        while units and unresolved and time.perf_counter() < deadline:\n            choices = []\n            for node in unresolved:\n                opposition = enemy[node]\n                ranked = sorted(\n                    range(len(units)),\n                    key=lambda i: (\n                        distances[units[i][0]][node],\n                        units[i][1] != node,\n                        units[i][0],\n                        i,\n                    ),\n                )\n                limit = min(len(units), opposition + 1)\n                max_distance = 0\n                for count in range(1, limit + 1):\n                    index = ranked[count - 1]\n                    max_distance = max(\n                        max_distance, distances[units[index][0]][node]\n                    )\n                    arrival = max(1, max_distance)\n                    if arrival > remaining:\n                        break\n                    # Under the visible-opponent-stays model, these orders\n                    # disappear this turn if an enemy already occupies the node.\n                    if opposition and arrival > 1:\n                        break\n\n                    reward_value = 0.0\n                    for reward, life in orders[node]:\n                        if life < arrival:\n                            continue\n                        ours, theirs = payout(count, opposition, reward)\n                        old_ours, old_theirs = payout(0, opposition, reward)\n                        reward_value += (\n                            ours - theirs - old_ours + old_theirs\n                        )\n                    if reward_value <= 0:\n                        continue\n\n                    chosen = ranked[:count]\n                    cost = 0.0\n                    sticky = 0.0\n                    for i in chosen:\n                        source, old_target = units[i]\n                        # Compare delivery followed by immediate return against\n                        # returning directly now. Travel upkeep and all return\n                        # upkeep are included, truncated at the game\'s end.\n                        direct_return = min(\n                            remaining, max(0, distances[source][base] - 1)\n                        )\n                        delivery_return = min(\n                            remaining,\n                            arrival + max(0, distances[node][base] - 1),\n                        )\n                        cost += UPKEEP * (delivery_return - direct_return)\n                        if old_target == node and source != base:\n                            sticky += 0.65\n\n                    net = reward_value - cost\n                    # Hysteresis never justifies an intrinsically losing trip.\n                    if net > 0.35:\n                        priority = net + sticky\n                        heapq.heappush(\n                            choices,\n                            (-priority, node, count, tuple(chosen)),\n                        )\n\n            if not choices:\n                break\n            _, node, count, chosen = heapq.heappop(choices)\n            targets[node] += count\n            selected = set(chosen)\n            units = [unit for i, unit in enumerate(units) if i not in selected]\n            unresolved.remove(node)\n\n        # Idle units return home; no speculative garrisons incur endless upkeep.\n        targets[base] += len(units)\n        return targets\n\n    def act(self, obs):\n        started = time.perf_counter()\n        deadline = started + max(0.0, 0.6 * TIME_BUDGET)\n        n = int(obs["n_nodes"])\n        key = (n, tuple(tuple(edge) for edge in obs["edges"]))\n        if key != self.map_key:\n            self.adjacency, self.distances = preprocess_map(n, obs["edges"])\n            self.map_key = key\n            self.missions = {}\n            self.previous_turn = None\n\n        if (\n            not obs.get("action_format_correct_last_turn", True)\n            or obs.get("n_invalid_actions_last_turn", 0) > 0\n        ):\n            self.bad_reports += 1\n\n        have = list(obs["player_units"])\n        base = int(obs["player_base"])\n        if self.bad_reports >= 2:\n            # Conservative recovery: a simple, validated return-home plan.\n            targets = [0] * n\n            targets[base] = sum(have)\n        else:\n            targets = self._plan(obs, deadline)\n\n        action, missions = legal_action(\n            have, targets, self.adjacency, self.distances\n        )\n        self.missions = missions\n        self.previous_turn = int(obs["turn"])\n        return action\n'
_CORE_CLASS = 'Strategy'
_FALLBACK_SRC = None
_FALLBACK_CLASS = 'Strategy'
_ACT_LIMIT_S = 0.7
